tool_input.command:
cat > /tmp/adw-review-notes.mjs <<'EOF'
import { generateNotes } from '@semantic-release/release-notes-generator';
const cfg = (await import(process.cwd() + '/release.config.js')).default;
const [, notesCfg] = cfg.plugins[1];
const ctx = {
  commits: [
    { hash: 'a'.repeat(40), message: 'build-agent: feat: add forgeProviders assembly' },
    { hash: 'b'.repeat(40), message: 'review-patch-agent: fix: correct token resolution' },
    { hash: 'c'.repeat(40), message: 'plan-orchestrator: chore: expand README' },
  ],
  logger: { log() {}, error() {} },
  cwd: process.cwd(),
  env: {},
  options: { repositoryUrl: 'https://github.com/paysdoc/devplatform.git' },
  lastRelease: { version: '1.0.0', gitTag: 'v1.0.0', gitHead: '0'.repeat(40) },
  nextRelease: { version: '1.1.0', gitTag: 'v1.1.0', gitHead: 'a'.repeat(40) },
};
try {
  const notes = await generateNotes(notesCfg, ctx);
  console.log('OK generateNotes rendered:\n' + notes);
} catch (e) {
  console.log('THROWS:', String(e.message).slice(0, 160));
  process.exit(1);
}
EOF
echo "preset installed: $(node -p "require('./node_modules/conventional-changelog-conventionalcommits/package.json').version")"; node /tmp/adw-review-notes.mjs; echo "exit: $?"
